import csv, json, os, re
from pathlib import Path
rows=[]
with open(\"ortg.tsv\", encoding=\"utf-8\", newline=\"\") as f:
    for row in csv.DictReader((line for line in f if not line.startswith(\"#\") and line.strip()), delimiter=\"\\t\"):
        p=row[\"path\"]
        if not row[\"outline\"] and (p.startswith(\"docs/\") or p==\"cextern/cfitsio/licenses/License.txt\"):
            rows.append(p)
allpaths=set()
with open(\"ortg.tsv\", encoding=\"utf-8\", newline=\"\") as f:
    for row in csv.DictReader((line for line in f if not line.startswith(\"#\") and line.strip()), delimiter=\"\\t\"):
        allpaths.add(row[\"path\"])
def clean(s,n=180):
    s=re.sub(r\"[:|\\[\\]\\t\\r\\n]+\",\" \",s); s=re.sub(r\"\\s+\",\" \",s).strip(\" -_=.#\"); return s[:n]
def title_of(text,p):
    ls=text.splitlines()
    for i,line in enumerate(ls[:-1]):
        t=clean(line,120); u=ls[i+1].strip()
        if t and len(u)>=3 and re.fullmatch(r\"[=~"'^'"\\-:#*+]+\",u): return t
    m=re.search(r\"<title["'^>]*>(.*?)</title>",text,re.I|re.S)
    if m:return clean(re.sub("<.*?>","",m.group(1)),120)
    for line in ls:
        s=clean(line.lstrip("#%!/ "),120)
        if s:return s
    return Path(p).stem.replace("_"," ").replace("-"," ")
def deps_of(text,p):
    out=[]; base=Path(p).parent
    for m in re.finditer(r"''^'"\\.\\.\\s+(?:literal)?include::\\s+(["'^'"\\s]+)\",text,re.M):
        q=m.group(1).strip(); q=q[1:] if q.startswith(\"/\") else str((base/q).as_posix()); q=os.path.normpath(q).replace(\"\\\\\",\"/\")
        if q in allpaths and q not in out:out.append(q)
    return out[:5]
def make(p):
    data=Path(p).read_bytes()
    try:text=data.decode(\"utf-8\")
    except UnicodeDecodeError:text=\"\"
    name=Path(p).name; ext=Path(p).suffix.lower(); lines=text.count(\"\\n\")+1 if text else 0
    size=\"L\" if lines>400 else \"M\" if lines>200 else \"S\" if lines>100 else \"T\"; title=title_of(text,p); low=p.lower(); importance=5
    if name==\".gitkeep\":
        importance=1; role=f\"保留 {Path(p).parent.as_posix()} 空目录以承载该子包的变更片段\"; cons=\"文件必须保持为空，仅用于版本控制保留变更片段分类目录。\"
    elif ext in {\".png\",\".ico\",\".pdf\",\".odg\"}:
        importance=3
        if \"time_scale_conversion\" in low:role=\"提供时间尺度转换关系的文档图示源文件或渲染图\"
        elif \"table_\" in low:role=f\"提供表格文档中 {Path(p).stem.replace('_',' ')} 示例的静态截图\"
        elif \"convolution/images\" in low:role=f\"提供卷积文档对 {Path(p).stem} 结果的示例图像\"
        elif \"branch\" in low or \"pull_button\" in low:role=\"提供贡献工作流文档所用的 GitHub 界面截图\"
        else:role=f\"提供 Astropy 文档站点使用的 {Path(p).stem.replace('_',' ')} 静态图像资产\"
        cons=\"二进制资产的格式、尺寸与引用路径属于文档构建输入，替换时须同步核对引用页面和明暗主题适配。\"
    elif ext==\".svg\":
        importance=3; role=f\"提供 Astropy 文档站点的 {Path(p).stem.replace('_',' ')} 矢量导航或品牌图形\"; cons=\"SVG 的可缩放图形、可访问文字及当前引用路径须保持与文档首页或主题模板一致。\"
    elif ext==\".css\":
        importance=5; role=\"定义 Astropy Sphinx 文档站点的项目级样式覆盖\"; cons=\"样式选择器须兼容当前 Sphinx 主题，并同时顾及常规页面、API 页面与明暗显示环境。\"
    elif p.endswith(\"_templates/layout.html\"):
        importance=5; role=\"扩展 Sphinx 基础布局并注入 Astropy 文档站点的自定义页面结构\"; cons=\"模板继承当前主题布局，新增块和静态资源引用必须保持 Sphinx/Jinja 模板兼容。\"
    elif p in {\"docs/Makefile\",\"docs/make.bat\"}:
        importance=5; role=\"为类 Unix 或 Windows 环境提供 Sphinx 文档构建入口\"; cons=\"构建目标把额外参数转交 sphinx-build，并以 docs/conf.py 作为配置、docs/_build 作为默认输出位置。\"
    elif p==\"docs/conf.py\":
        importance=8; role=\"配置 Astropy 文档的 Sphinx 扩展、自动 API、交叉引用、主题、版本与构建行为\"; cons=\"文档构建依赖项目可导入及配置的扩展；警告、nitpick 忽略、API 生成、主题静态资源和版本切换设置共同决定发布文档，不应孤立修改。\"
    elif p==\"docs/conftest.py\":
        importance=5; role=\"为文档示例测试提供 pytest 配置与共享行为\"; cons=\"仅服务文档测试收集和示例执行；行为须与根级 conftest.py 及文档构建约定兼容。\"
    elif p==\"docs/rtd_environment.yaml\":
        importance=5; role=\"声明 Read the Docs 文档构建使用的 Conda 环境依赖\"; cons=\"环境依赖须足以导入 Astropy、执行文档示例并构建全部扩展，同时与受支持 Python 和文档 CI 配置一致。\"
    elif ext==\".csv\":
        importance=3; role=f\"提供 {title} 文档示例使用的时序数据集\"; cons=\"列名、时间表示、采样值和缺失数据形态是示例读取与分析流程的输入格式，不得随意改写。\"
    elif \"/whatsnew/\" in p:
        importance=5; role=f\"汇总并讲解 Astropy {title} 的用户可见新增功能和迁移要点\"; cons=\"内容按发布版本保留历史事实，并通过示例或交叉引用指向相应子包；不得把后续版本行为回写为该版本既有能力。\"
    elif name in {\"ref_api.rst\",\"reference_api.rst\",\"misc_ref_api.rst\",\"registry_ref_api.rst\"} or \"/api/\" in p:
        importance=5; role=f\"组织 {title} 的公开 API 参考与自动文档入口\"; cons=\"autosummary、automodule、autoclass 与交叉引用中的公开导入路径必须对应实际导出接口；增删 API 时须同步更新列表。\"
    elif name==\"index.rst\":
        importance=7; role=f\"作为 {title} 的主题入口，组织概念说明、教程与参考页面导航\"; cons=\"toctree 层级、页面路径和交叉引用构成该主题文档导航；新增或移动页面须同步维护目录且避免孤立页面。\"
    elif name.endswith(\"performance.inc\"):
        importance=3; role=f\"提供 {title} 文档复用的性能提示片段\"; cons=\"这是被其他页面 include 的共享片段；内容与标题层级须适合嵌入上下文，修改时同步核对所有引用页。\"
    elif ext==\".py\":
        importance=5; role=f\"提供文档中 {title} 的可执行示例代码\"; cons=\"示例必须可在文档构建环境运行，并以公开 Astropy API 展示可复现流程；输出和绘图应与引用页面叙述一致。\"
    elif p==\"cextern/cfitsio/licenses/License.txt\":
        importance=9; role=\"载明内嵌 CFITSIO 源码的许可授权、再分发条件与免责声明\"; cons=\"再分发内嵌 CFITSIO 时必须保留版权和许可文本；软件按现状提供，作者与 NASA 不承担使用产生的责任。\"
    else:
        role=f\"讲解 {title}，为 Astropy 用户或贡献者提供该主题的概念、操作与参考说明\"; heads=[]; ls=text.splitlines()
        for i,line in enumerate(ls[:-1]):
            h=clean(line,80);u=ls[i+1].strip()
            if h and len(u)>=3 and re.fullmatch(r\"[=~"'^'"\\-:#*+]+\",u) and h"'!=title and h not in heads:heads.append(h)
        cons=("页面以"+"、".join(heads[:6])+"等章节组织既有用法与约定；代码示例和交叉引用须与公开 API 保持一致。") if heads else "文档中的示例、参数名、默认行为和交叉引用须与当前公开 API 及相邻主题页面保持一致。"
    deps=deps_of(text,p);uses=",".join(f"{d}(嵌入内容)" for d in deps) if deps else "-"
    return {"path":p,"outline":f"{name}[{importance} O G {size}]: Role:{clean(role,300)} | Uses:{uses} | API:- | Constraints:{clean(cons,900)}"}
items=[make(p) for p in rows]
print(json.dumps(items[:25],ensure_ascii=False,indent=2));print("COUNT",len(items))
